// @FIGURE_CODE_BEGIN
// shaded known-greater region → ShapeGeometry rounded stepped polygon, light gray, behind c3-lower and c4-c6 median-and-below
// shaded known-less region    → ShapeGeometry rounded stepped polygon, light gray, mirrored proof side
// element circles             → CircleGeometry filled black or white plus RingGeometry black stroke for medians
// vertical comparison arrows  → TubeGeometry straight LineCurve3 strokes plus triangular Mesh arrowheads
// long column arrows          → TubeGeometry CubicBezierCurve3 left-bowed arcs plus triangular Mesh arrowheads
// median-row arrows           → TubeGeometry horizontal/Bezier comparison arcs plus triangular Mesh arrowheads
// x click target              → transparent CircleGeometry hit mesh over the third-column median and x label
// label x                     → addLabel italic HTML label near third-column median

const black = 0x000000;
const white = 0xffffff;
const gray = 0xbfbfbf;
const orange = 0xff9900;
const paleOrange = 0xfff0d6;
const r = 0.16;
const cols = [-3.0, -1.75, -0.5, 0.75, 2.0, 3.25];
const fullYs = [2.25, 1.1, 0, -1.1, -2.25];
const shortYs = [1.1, 0, -1.1];

const allArrows = [];
const verticalArrows = [];
const longArrows = [];
const medianArrows = {};
const circles = new Map();

function makeMat(color, opts = {}) {
  return new THREE.MeshBasicMaterial({
    color,
    side: THREE.DoubleSide,
    transparent: !!opts.transparent,
    opacity: opts.opacity ?? 1,
    depthTest: false,
    depthWrite: false
  });
}

function setObjColor(obj, color) {
  obj.traverse(o => {
    if (o.material && o.material.color) o.material.color.setHex(color);
  });
}

function makeKnownGreaterShape() {
  const s = new THREE.Shape();
  s.moveTo(-0.68, -2.75);
  s.lineTo(2.35, -2.75);
  s.quadraticCurveTo(2.65, -2.75, 2.65, -2.45);
  s.lineTo(2.65, -1.78);
  s.lineTo(3.45, -1.78);
  s.quadraticCurveTo(3.75, -1.78, 3.75, -1.48);
  s.lineTo(3.75, 0.35);
  s.quadraticCurveTo(3.75, 0.65, 3.45, 0.65);
  s.lineTo(0.45, 0.65);
  s.quadraticCurveTo(0.15, 0.65, 0.15, 0.35);
  s.lineTo(0.15, -0.28);
  s.quadraticCurveTo(0.15, -0.55, -0.12, -0.55);
  s.lineTo(-0.65, -0.55);
  s.quadraticCurveTo(-0.95, -0.55, -0.95, -0.85);
  s.lineTo(-0.95, -2.45);
  s.quadraticCurveTo(-0.95, -2.75, -0.68, -2.75);
  return s;
}

function makeKnownLessShape() {
  const s = new THREE.Shape();
  s.moveTo(-3.25, -0.65);
  s.lineTo(-1.15, -0.65);
  s.quadraticCurveTo(-0.85, -0.65, -0.85, -0.35);
  s.lineTo(-0.85, 0.55);
  s.lineTo(-0.15, 0.55);
  s.quadraticCurveTo(0.10, 0.55, 0.10, 0.80);
  s.lineTo(0.10, 2.45);
  s.quadraticCurveTo(0.10, 2.75, -0.20, 2.75);
  s.lineTo(-3.25, 2.75);
  s.quadraticCurveTo(-3.55, 2.75, -3.55, 2.45);
  s.lineTo(-3.55, -0.35);
  s.quadraticCurveTo(-3.55, -0.65, -3.25, -0.65);
  return s;
}

const shadeGreater = new THREE.Mesh(new THREE.ShapeGeometry(makeKnownGreaterShape()), makeMat(gray));
shadeGreater.position.z = -0.10;
shadeGreater.renderOrder = 0;
scene.add(shadeGreater);

const shadeLess = new THREE.Mesh(new THREE.ShapeGeometry(makeKnownLessShape()), makeMat(gray));
shadeLess.position.z = -0.10;
shadeLess.renderOrder = 0;
scene.add(shadeLess);

function makeCircle(colIndex, x, y, isMedian) {
  const group = new THREE.Group();
  group.position.set(x, y, 0.03);
  group.renderOrder = 6;

  const fill = new THREE.Mesh(new THREE.CircleGeometry(r, 72), makeMat(isMedian ? white : black));
  fill.renderOrder = 6;
  group.add(fill);

  const stroke = new THREE.Mesh(new THREE.RingGeometry(r * 0.90, r * 1.08, 72), makeMat(black));
  stroke.position.z = 0.014;
  stroke.renderOrder = 7;
  stroke.visible = isMedian;
  group.add(stroke);

  scene.add(group);
  const item = { group, fill, stroke, colIndex, x, y, isMedian };
  circles.set(`${colIndex}:${y}`, item);
  return item;
}

for (let i = 0; i < cols.length; i++) {
  const ys = i === 5 ? shortYs : fullYs;
  for (const y of ys) makeCircle(i + 1, cols[i], y, y === 0);
}

function arrowHead(tip, dir, color = black, z = 0.09, len = 0.25, wid = 0.19) {
  const d2 = new THREE.Vector2(dir.x, dir.y).normalize();
  const p = new THREE.Vector2(-d2.y, d2.x);
  const base = new THREE.Vector2(tip.x, tip.y).sub(d2.clone().multiplyScalar(len));
  const a = new THREE.Vector3(tip.x, tip.y, z);
  const b = new THREE.Vector3(base.x + p.x * wid * 0.5, base.y + p.y * wid * 0.5, z);
  const c = new THREE.Vector3(base.x - p.x * wid * 0.5, base.y - p.y * wid * 0.5, z);
  const geom = new THREE.BufferGeometry();
  geom.setAttribute('position', new THREE.Float32BufferAttribute([
    a.x, a.y, a.z,
    b.x, b.y, b.z,
    c.x, c.y, c.z
  ], 3));
  geom.setIndex([0, 1, 2]);
  geom.computeVertexNormals();
  const mesh = new THREE.Mesh(geom, makeMat(color));
  mesh.renderOrder = 5;
  return mesh;
}

function makeArrow(id, curve, opts = {}) {
  const group = new THREE.Group();
  const color = opts.color ?? black;
  const radius = opts.radius ?? 0.0125;
  const tube = new THREE.Mesh(new THREE.TubeGeometry(curve, opts.segments ?? 64, radius, 8, false), makeMat(color));
  tube.renderOrder = 4;
  group.add(tube);

  const t = opts.headT ?? 1;
  const tip = curve.getPoint(t);
  const tangent = curve.getTangent(t).normalize();
  const head = arrowHead(tip, tangent, color, 0.09, opts.headLen ?? 0.25, opts.headWid ?? 0.19);
  group.add(head);

  group.userData.id = id;
  group.userData.tube = tube;
  group.userData.head = head;
  scene.add(group);
  allArrows.push(group);
  return group;
}

function straightArrow(id, x1, y1, x2, y2) {
  const curve = new THREE.LineCurve3(new THREE.Vector3(x1, y1, 0.07), new THREE.Vector3(x2, y2, 0.07));
  return makeArrow(id, curve, { segments: 1 });
}

function cubicArrow(id, p0, p1, p2, p3, opts = {}) {
  const curve = new THREE.CubicBezierCurve3(
    new THREE.Vector3(p0[0], p0[1], 0.07),
    new THREE.Vector3(p1[0], p1[1], 0.07),
    new THREE.Vector3(p2[0], p2[1], 0.07),
    new THREE.Vector3(p3[0], p3[1], 0.07)
  );
  return makeArrow(id, curve, { segments: opts.segments ?? 92, headT: opts.headT ?? 1, headLen: opts.headLen, headWid: opts.headWid });
}

for (let i = 0; i < cols.length; i++) {
  const x = cols[i];
  verticalArrows.push(straightArrow(`c${i + 1}-low-to-med`, x, -0.92, x, -0.20));
  verticalArrows.push(straightArrow(`c${i + 1}-med-to-up`, x, 0.20, x, 0.92));
}

for (let i = 0; i < 5; i++) {
  const x = cols[i];
  longArrows.push(cubicArrow(
    `c${i + 1}-bottom-to-top`,
    [x - 0.15, -2.05],
    [x - 0.50, -1.20],
    [x - 0.50, 1.18],
    [x - 0.17, 1.88],
    { segments: 110, headLen: 0.28, headWid: 0.20 }
  ));
}

medianArrows.c3c2 = straightArrow('median-c3-to-c2', -0.70, 0.00, -1.55, 0.00);
medianArrows.c3c1 = cubicArrow('median-c3-to-c1', [-0.68, 0.03], [-1.25, 0.29], [-2.38, 0.31], [-2.82, 0.12], { segments: 90 });
medianArrows.c4c3 = straightArrow('median-c4-to-c3', 0.55, 0.00, -0.30, 0.00);
medianArrows.c5c3 = cubicArrow('median-c5-to-c3', [1.80, 0.03], [1.23, 0.34], [0.35, 0.31], [-0.30, 0.06], { segments: 90 });
medianArrows.c6c3 = cubicArrow('median-c6-to-c3', [3.05, 0.05], [2.35, 0.80], [0.58, 0.77], [-0.30, 0.09], { segments: 120 });

const xHit = new THREE.Mesh(new THREE.CircleGeometry(0.48, 48), makeMat(orange, { transparent: true, opacity: 0 }));
xHit.position.set(-0.25, -0.12, 0.13);
xHit.renderOrder = 10;
scene.add(xHit);

registerInteractive(xHit, {
  title: 'Median of medians x',
  tooltip: 'Click x to highlight certified comparison chains',
  body: 'The element x is chosen from the row of group medians. The arrows show transitive chains: once a group median is known to be on one side of x, several ordinary elements in that group are certified on the same side.',
  onClick: () => {
    highlighted = !highlighted;
    updateVisuals();
  }
});

setCameraView({
  projection: 'orthographic',
  axisScreenAngles: null,
  rollDeg: 0,
  heightFraction: 0.75
});

const xLabel = addLabel('<i>x</i>', new THREE.Vector3(-0.28, -0.30, 0.14), {
  fontSize: '32px',
  color: '#000',
  offset: [0, 0]
});

const phaseSelect = document.getElementById('proofPhase');
const sideSelect = document.getElementById('partitionSide');
const highlightBtn = document.getElementById('highlightChains');
const demoSelect = document.getElementById('demoStep');
const prevBtn = document.getElementById('prevStep');
const nextBtn = document.getElementById('nextStep');
const narrationBox = document.getElementById('stepNarration');

const demoSteps = [
  {
    title: 'Group into fives',
    narration: 'The elements are arranged as vertical groups of five, with a short final group at the right. At this first phase the learner sees the grouping structure before any counting argument is added.',
    state: { proofPhase: 'groupIntoFives', partitionSide: 'Known greater than x' }
  },
  {
    title: 'Mark group medians',
    narration: 'The middle element of each group is shown as an open circle. These medians summarize each group after the elements inside the group have been ordered.',
    state: { proofPhase: 'markGroupMedians', partitionSide: 'Known greater than x' }
  },
  {
    title: 'Choose x',
    narration: 'The third median is labeled x, the median of the group medians in this schematic. Arrows along the median row show which group medians are known to lie on either side of x.',
    state: { proofPhase: 'chooseX', partitionSide: 'Known greater than x' }
  },
  {
    title: 'Count known-greater elements',
    narration: 'The gray region appears on the source-figure side: elements in groups whose medians are beyond x are counted together with the elements below those medians in the drawing. Clicking x highlights the comparison chains that certify these elements relative to x.',
    state: { proofPhase: 'shadeKnownSide', partitionSide: 'Known greater than x' }
  },
  {
    title: 'Switch to the symmetric side',
    narration: 'The shaded block switches to the opposite side of x. The learner sees that the proof gives the same kind of lower bound for elements known to be less than x.',
    state: { proofPhase: 'shadeKnownSide', partitionSide: 'Known less than x' }
  }
];

let proofPhase = 'shadeKnownSide';
let partitionSide = 'Known greater than x';
let highlighted = false;
let currentStep = 3;

function circleAt(col, y) {
  return circles.get(`${col}:${y}`);
}

function setCircleHighlight(item, on) {
  if (!item) return;
  if (item.isMedian) {
    item.stroke.material.color.setHex(on ? orange : black);
    item.fill.material.color.setHex(on ? paleOrange : white);
  } else {
    item.fill.material.color.setHex(on ? orange : black);
  }
}

function resetCircleStyles(mediansOpen) {
  for (const item of circles.values()) {
    if (item.isMedian) {
      item.fill.material.color.setHex(mediansOpen ? white : black);
      item.stroke.visible = mediansOpen;
      item.stroke.material.color.setHex(black);
    } else {
      item.fill.material.color.setHex(black);
    }
  }
}

function arrowVisible(group, visible) {
  group.visible = visible;
}

function resetArrowColors() {
  for (const a of allArrows) setObjColor(a, black);
}

function showArrowSet(arr, visible) {
  for (const a of arr) arrowVisible(a, visible);
}

function highlightArrow(group) {
  if (group) setObjColor(group, orange);
}

function setHighlightedCirclesForSide(side) {
  setCircleHighlight(circleAt(3, 0), true);
  if (side === 'Known greater than x') {
    [-1.1, -2.25].forEach(y => setCircleHighlight(circleAt(3, y), true));
    [4, 5].forEach(c => [0, -1.1, -2.25].forEach(y => setCircleHighlight(circleAt(c, y), true)));
    [0, -1.1].forEach(y => setCircleHighlight(circleAt(6, y), true));
  } else {
    [1.1, 2.25].forEach(y => setCircleHighlight(circleAt(3, y), true));
    [1, 2].forEach(c => [0, 1.1, 2.25].forEach(y => setCircleHighlight(circleAt(c, y), true)));
  }
}

function highlightChainsForSide(side) {
  if (side === 'Known greater than x') {
    highlightArrow(medianArrows.c4c3);
    highlightArrow(medianArrows.c5c3);
    highlightArrow(medianArrows.c6c3);
    for (const a of verticalArrows) {
      if (/c[3456]-low-to-med/.test(a.userData.id)) highlightArrow(a);
    }
    for (const a of longArrows) {
      if (/c[345]-bottom-to-top/.test(a.userData.id)) highlightArrow(a);
    }
  } else {
    highlightArrow(medianArrows.c3c2);
    highlightArrow(medianArrows.c3c1);
    for (const a of verticalArrows) {
      if (/c[123]-med-to-up/.test(a.userData.id)) highlightArrow(a);
    }
    for (const a of longArrows) {
      if (/c[123]-bottom-to-top/.test(a.userData.id)) highlightArrow(a);
    }
  }
}

function updateVisuals() {
  const mediansOpen = proofPhase !== 'groupIntoFives';
  const showInternal = proofPhase === 'markGroupMedians' || proofPhase === 'chooseX' || proofPhase === 'shadeKnownSide';
  const showMedianRow = proofPhase === 'chooseX' || proofPhase === 'shadeKnownSide';
  const showShade = proofPhase === 'shadeKnownSide';

  resetCircleStyles(mediansOpen);
  resetArrowColors();

  showArrowSet(verticalArrows, showInternal);
  showArrowSet(longArrows, showInternal);
  Object.values(medianArrows).forEach(a => arrowVisible(a, showMedianRow));

  shadeGreater.visible = showShade && partitionSide === 'Known greater than x';
  shadeLess.visible = showShade && partitionSide === 'Known less than x';

  xLabel.div.style.visibility = showMedianRow ? 'visible' : 'hidden';
  xLabel.div.style.color = highlighted && showMedianRow ? '#ff9900' : '#000';

  if (highlighted && showMedianRow) {
    setHighlightedCirclesForSide(partitionSide);
    highlightChainsForSide(partitionSide);
  }

  highlightBtn.classList.toggle('active', highlighted);
}

phaseSelect.addEventListener('change', () => {
  proofPhase = phaseSelect.value;
  highlighted = false;
  for (let i = 0; i < demoSteps.length; i++) {
    if (demoSteps[i].state.proofPhase === proofPhase && demoSteps[i].state.partitionSide === partitionSide) {
      currentStep = i;
      demoSelect.value = String(i);
      narrationBox.innerHTML = `<b>${demoSteps[i].title}</b><br>${demoSteps[i].narration}`;
      break;
    }
  }
  updateVisuals();
});

sideSelect.addEventListener('change', () => {
  partitionSide = sideSelect.value;
  updateVisuals();
});

highlightBtn.addEventListener('click', () => {
  highlighted = !highlighted;
  updateVisuals();
  showPopup(
    'Certified chains',
    partitionSide === 'Known greater than x'
      ? 'Orange marks the arrows from the right-side medians into x and the within-group arrows certifying the shaded lower elements.'
      : 'Orange marks the symmetric arrows from x toward the left-side medians and the within-group arrows certifying upper elements.'
  );
});

function goToStep(i) {
  currentStep = Math.max(0, Math.min(demoSteps.length - 1, i | 0));
  const step = demoSteps[currentStep];
  proofPhase = step.state.proofPhase;
  partitionSide = step.state.partitionSide;
  highlighted = false;
  phaseSelect.value = proofPhase;
  sideSelect.value = partitionSide;
  demoSelect.value = String(currentStep);
  narrationBox.innerHTML = `<b>${step.title}</b><br>${step.narration}`;
  updateVisuals();
}
window.goToStep = goToStep;

demoSelect.addEventListener('change', () => goToStep(Number(demoSelect.value)));
prevBtn.addEventListener('click', () => goToStep(currentStep - 1));
nextBtn.addEventListener('click', () => goToStep(currentStep + 1));

goToStep(3);
// @FIGURE_CODE_END

